                              \/ rn_tp rn + rn_loff rn <= a < rn_tp rn + rn_loff rn + 4) -> hl_rt_static L a.
Hypothesis HLro : forall a, 0x10000 <= a < 0x158000 -> hl_rt_ro L a.
Hypothesis HLcs : forall a, (0x158bb0 <= a < 0x158bb8 \/ 0x158c78 <= a < 0x158c90 \/ rn_tp rn + 8 <= a < rn_tp rn + 16) -> hl_rt_static L a.   (* [comment removed for export] *)

