Section FPX_1. Context {fx : PropExec.FPState}.

#[local] Ltac rwH :=
  repeat match goal with
         | H : getr ?rg ?i = _ |- context [getr ?rg ?i] => rewrite !H
         end.
#[local] Ltac unorm :=
  repeat match goal with
         | |- context [bv_unsigned (Z_to_bv 64 ?z)] =>
             lazymatch z with context [Z_to_bv 64 _] => fail | _ => rewrite (u_Z2bv z) by lia end
         end.
#[local] Ltac cond :=
  rwH; unfold at_, v_addi, v_add, c_eq, c_ltu, bv_eqb, bv_ltu; imm_norm; unorm;
  first [apply Z.eqb_eq | apply Z.eqb_neq | apply Z.ltb_lt | apply Z.ltb_ge]; lia.
#[local] Ltac wval :=
  gres; rwH; unfold at_, v_addi, v_add, v_sub, v_srli; imm_norm; unorm; rewrite ?Z.shiftr_div_pow2 by lia;
  try change (2 ^ 3)%Z with 8%Z; first [reflexivity | f_equal; lia].
#[local] Ltac maddr z := match goal with |- rdn _ _ ?ad _ = _ => replace ad with (Z_to_bv 64 z) by (symmetry; wval) end.
#[local] Ltac mldq F D z R :=
  chain_step; [reflexivity
    | eapply step_ld with (bs := word_to_le_bytes 8 (Z_to_bv 64 _)); [exact F | reflexivity | exact D | maddr z; exact R | exact (bytes_le_to_Z_8 _)]
    | step_simpl; vnorm].
(* [comment removed for export] *)
#[local] Ltac stepsdq F D aa vv oktac :=
  chain_step; [reflexivity
    | eapply step_sd_at with (a := aa) (v := vv); [exact F | reflexivity | exact D | wval | gres; rwH; first [reflexivity | f_equal; lia] | oktac]
    | step_simpl].
#[local] Ltac mlbq F D z R :=
  chain_step; [reflexivity
    | eapply step_lb; [exact F | reflexivity | exact D | maddr z; exact R]
    | step_simpl; vnorm].

#[using="Type"] Lemma wbytes_out_any : forall bs m (addr x : word),
  (bv_unsigned addr + Z.of_nat (length bs) <= 2 ^ 64)%Z ->
  (bv_unsigned x < bv_unsigned addr \/ bv_unsigned addr + Z.of_nat (length bs) <= bv_unsigned x)%Z ->
  wbytes m addr bs x = m x.
Proof.
ltac2:(KReplay.run1 (kr_t_Na0HandleNoReturn ()) ["FPX_1"] "h02Hxh11Hh23Hnwh34addrh42bsh51mh61xp;1p;2p;4p;3p;6p;5p-1R0p10000p4p710p9P0p1000Sp4p710p9P0p1001?R1p4p710p9P0P1p4p7210p9P0P1p4p73110p9P0p1001]p4p710p9P0p1002Dp4p710p9P0p1003<p4p710R1p8P0p1003SR2p4p710p8P0P2p4p7210p8P0p1003oR2p4p710p8P0P2p4p7210p8p1004Lp4p70R2P1p8P2p1005Jp4p710R1p8P2p1005gp4p710p8P1p1006Dp4p710R1p8p1006bp6051003R2p1007jp4p710R0p8p1008fp4p7210R3p1009Rp4p710p8P3P1p8p1009np6051001R3P0p8P3P2p8P3p100;@p4p710R2p8P3p100<Hp4p710R4p8P3p100=Op4p710R5p8P3p100>Up4p710R6p8P3p100?\p4p710R7p8P3p100@bp4p710R8p8P3p100Agp4p710R9p8P3p100Bop4p710R3p8p100D8p6051003R:P0p8p100EDp6051001R;P0p8P;P2p8P;P:p8P;P4p8P;P5p8P;P6p8P;P7p8P;P8p8P;P9p8P;P3p8p100F\p6051001R3P0p8P3P;p8p100Glp4p7210P1p8g00I@j10Tg01E\j19Tg01F:j18Tg00M5j1;Tg01F]j1ATg01G?j25Tg01Gij23Tg01HIj12Tg00L8j21Tg00Iej17Tg00J`j2:Tg00HIj24Tg00Umj26Tg00^BR1j2@Tg01Hij4?Tg00aHj3>Tg01Idj6<Tg01Jej5=Tg00m6#0R;#0#0R3#9#8R0#;%03#0#0R3#9R9#8R8%A0R7[f1,59R6f3R5,30#2'1%7;%73':'4f2,59R3,66f4R;,30#2,13/46'@P11595R1,63f5R6,30#2,11/43P6P;f6R3P5C?P6P5O15>7f0R7159;R9,61f7R4P3P6P;P5P7E<W0P7O11303#2,19/41P4P3P6P;P7D=W0P7O1n200100000021000010000W1W2X68X38W5W4o"). Qed.

