  { rewrite <- !bytes_le_N. rewrite W. reflexivity. }
  change (2 ^ (8 * Z.of_nat 8)) with (2 ^ 64) in E.
  rewrite !art_u_lit in E by (unfold FS_BYTES in *; lia). rewrite !Z.mod_small in E by (unfold FS_BYTES in *; lia).
